223	// QueryLine 解析并执行一行查询对象。成功返回 QueryResult；查询只读，不改变存储。
224	func (s *MetricStore) QueryLine(line string) (*QueryResult, *LineError) {
225		top, ok, lerr := decodeTopValue(line)
226		if lerr != nil {
227			return nil, lerr
228		}
229		if ok != '{' {
230			return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a query object"}
231		}
232		return s.queryFromObject(top)
233	}
