29	func TestIngestBasicSuccessAndSnapshot(t *testing.T) {
30		store := NewMetricStore()
31		res := mustOK(t, store, `[
32			{"name":"cpu","timestamp":2000,"value":0.5,"labels":{"host":"b"}},
33			{"name":"cpu","timestamp":1000,"value":0.25,"labels":{"host":"a"}},
34			{"name":"mem","timestamp":1000,"value":1}
