112	func TestFailedBatchRollsBackEntireLine(t *testing.T) {
113		store := NewMetricStore()
114		mustOK(t, store, `[{"name":"old","timestamp":1,"value":9}]`)
115	
116		// 本批第一个点是新增，第二个点与历史冲突：整批都不得生效。
117		mustFail(t, store, `[{"name":"new","timestamp":1,"value":1},{"name":"old","timestamp":1,"value":100}]`)
118	
