func TestQueryAverageSubnormalAndRounding(t *testing.T) {
	// 最小次正规值参与平均不得被提前冲刷为零。
	store := NewMetricStore()
	mustOK(t, store, `[
		{"name":"m","timestamp":1,"value":5e-324},
		{"name":"m","timestamp":2,"value":5e-324}
	]`)
