	}

	// 单点序列返回该点的值本身。
	store3 := NewMetricStore()
	mustOK(t, store3, `[{"name":"m","timestamp":7,"value":0.1}]`)
	res = mustQuery(t, store3, `{"op":"query","name":"m","start":0,"end":10}`)
