package main

import (
	"bytes"
	"strings"
	"testing"
)

// 端到端回归保障：同一进程内先成功写入基线点（cpu、host=a、ts=1000、value=2），
// 随后各失败批次的“用户收到的失败原因”与“数据状态”必须同时正确：
//
//   - 数值冲突与字段类型错误出现在不同采样点时，只报告数组位置更靠前的那一个；
//     冲突结果带完整 conflict（指标名、完整标签、时间戳、existing/submitted），
//     字段错误不附带 conflict，交换两类问题点的位置后原因随之切换。
//   - 同一采样点同时具备冲突条件与未知字段 bogus 时，无论 bogus 写在何处，
//     都报未知字段而非冲突。
//   - 数组未闭合只产生整行解析错误，不带 index 与 conflict，即使行内前面的
//     采样点已具备冲突条件。
//
// 每个失败批次只输出一条带原始输入行号的 error（index 从 1 开始），不夹带
// 成功结果或任何部分统计；失败批次前面的新增点不留下、已存值不被覆盖，
// 失败后查询仍只见基线点；之后的合法批次正常新增。输入中出现过失败行时，
// 命令最终返回非零退出码。
func TestRunIngestBatchConflictSelectionEndToEnd(t *testing.T) {
	input := strings.Join([]string{
		// 行 1：先成功写入基线点。
		`[{"name":"cpu","timestamp":1000,"value":2,"labels":{"host":"a"}}]`,
		// 行 2：第一个点是 ts=2000 的合法新增，第二个点在 ts=1000 冲突，
		// 第三个点 name 为数字。只报告第二个点的冲突。
		`[{"name":"cpu","timestamp":2000,"value":4,"labels":{"host":"a"}},` +
			`{"name":"cpu","timestamp":1000,"value":9,"labels":{"host":"a"}},` +
			`{"name":7,"timestamp":3000,"value":1,"labels":{"host":"a"}}]`,
		// 行 3：交换后两个点：第二个点 name 类型错误，第三个点才是冲突。
		`[{"name":"cpu","timestamp":2000,"value":4,"labels":{"host":"a"}},` +
			`{"name":7,"timestamp":3000,"value":1,"labels":{"host":"a"}},` +
			`{"name":"cpu","timestamp":1000,"value":9,"labels":{"host":"a"}}]`,
		// 行 4：同一采样点既冲突又带未知字段 bogus（bogus 在所有已知字段之后）。
		`[{"name":"cpu","timestamp":1000,"value":9,"labels":{"host":"a"},"bogus":1}]`,
		// 行 5：同样的采样点，name/timestamp/value 都写在 bogus 前面，labels 在其后。
		`[{"name":"cpu","timestamp":1000,"value":9,"bogus":1,"labels":{"host":"a"}}]`,
		// 行 6：数组未闭合，前面的点已具备冲突条件：只能是整行解析错误。
		`[{"name":"cpu","timestamp":2000,"value":4,"labels":{"host":"a"}},` +
			`{"name":"cpu","timestamp":1000,"value":9,"labels":{"host":"a"}`,
		// 行 7：失败批次均回滚后，查询覆盖两个时间戳仍只见基线点。
		`{"op":"query","name":"cpu","start":0,"end":3000,"labels":{"host":"a"}}`,
		// 行 8：提交 ts=2000、value=4 的合法批次，正常新增。
		`[{"name":"cpu","timestamp":2000,"value":4,"labels":{"host":"a"}}]`,
		// 行 9：再次查询得到两个点、均值 3。
		`{"op":"query","name":"cpu","start":0,"end":3000,"labels":{"host":"a"}}`,
	}, "\n")

	var out bytes.Buffer
	code := runIngest(strings.NewReader(input), &out)
	if code == 0 {
		t.Fatalf("exit code = 0, want non-zero because failure lines occurred")
	}

	lines := strings.Split(strings.TrimRight(out.String(), "\n"), "\n")
	if len(lines) != 9 {
		t.Fatalf("got %d output lines, want 9 (one result per non-blank input line): %v",
			len(lines), lines)
	}

	// assertBareError 校验失败记录：恰好一条 error、原始行号正确、index 期望，
	// 且不夹带任何成功结果或部分统计（added/duplicates/series/op 均不得出现）。
	assertBareError := func(idx, wantLine, wantIndex int) map[string]interface{} {
		t.Helper()
		m := decodeResultLine(t, lines[idx])
		if m["status"] != "error" {
			t.Fatalf("output %d = %v, want status error", idx, m)
		}
		if int(m["line"].(float64)) != wantLine {
			t.Fatalf("output %d line = %v, want input line %d", idx, m["line"], wantLine)
		}
		if wantIndex == 0 {
			if _, has := m["index"]; has {
				t.Fatalf("output %d must not carry index: %v", idx, m)
			}
		} else if int(m["index"].(float64)) != wantIndex {
			t.Fatalf("output %d index = %v, want %d", idx, m["index"], wantIndex)
		}
		for _, k := range []string{"added", "duplicates", "series", "op"} {
			if _, has := m[k]; has {
				t.Fatalf("failed batch output %d must not carry success/stat field %q: %v", idx, k, m)
			}
		}
		return m
	}

	// 行 1：成功写入基线点。
	if m := decodeResultLine(t, lines[0]); m["status"] != "ok" ||
		m["added"].(float64) != 1 || m["duplicates"].(float64) != 0 {
		t.Fatalf("line 1 = %v, want successful write of the single baseline point", m)
	}

	// 行 2：只报第二个采样点的数值冲突，完整 conflict 细节对应这个点。
	m := assertBareError(1, 2, 2)
	if m["error"] != "conflict: series cpu{host=a} at timestamp 1000 already has value 2, submitted 9" {
		t.Fatalf("line 2 error = %v", m["error"])
	}
	conflict, ok := m["conflict"].(map[string]interface{})
	if !ok {
		t.Fatalf("line 2 must carry conflict detail: %v", m)
	}
	cSeries := conflict["series"].(map[string]interface{})
	if cSeries["name"] != "cpu" {
		t.Fatalf("line 2 conflict series name = %v, want cpu", cSeries["name"])
	}
	cLabels := cSeries["labels"].(map[string]interface{})
	if len(cLabels) != 1 || cLabels["host"] != "a" {
		t.Fatalf("line 2 conflict labels = %v, want exactly host=a", cLabels)
	}
	if conflict["timestamp"].(float64) != 1000 ||
		conflict["existing"].(float64) != 2 || conflict["submitted"].(float64) != 9 {
		t.Fatalf("line 2 conflict detail = %v, want ts=1000 existing=2 submitted=9", conflict)
	}

	// 行 3：交换后只报第二个点的 name 类型错误，不附带 conflict。
	m = assertBareError(2, 3, 2)
	if !strings.Contains(m["error"].(string), `field "name" must be a string`) {
		t.Fatalf("line 3 error = %v, want name type error", m["error"])
	}
	if _, has := m["conflict"]; has {
		t.Fatalf("line 3 field error must not carry conflict: %v", m)
	}

	// 行 4、行 5：同一采样点的未知字段错误压过数值冲突，均无 conflict。
	for idx, wantLine := range []int{4, 5} {
		m := assertBareError(3+idx, wantLine, 1)
		if m["error"] != `unknown field "bogus"` {
			t.Fatalf("line %d error = %v, want unknown field bogus", wantLine, m["error"])
		}
		if _, has := m["conflict"]; has {
			t.Fatalf("line %d field error must not carry conflict: %v", wantLine, m)
		}
	}

	// 行 6：数组未闭合 → 整行解析错误，无 index、无 conflict。
	m = assertBareError(5, 6, 0)
	if !strings.Contains(m["error"].(string), "invalid JSON") {
		t.Fatalf("line 6 error = %v, want invalid JSON parse error", m["error"])
	}
	if _, has := m["conflict"]; has {
		t.Fatalf("line 6 parse error must not carry conflict: %v", m)
	}

	// 行 7：失败批次前的新增点未留下、原值未覆盖——只剩 host=a 的一个点。
	q := decodeResultLine(t, lines[6])
	if q["status"] != "ok" || q["op"] != "query" {
		t.Fatalf("line 7 = %v, want ok query", q)
	}
	qSeries := q["series"].([]interface{})
	if len(qSeries) != 1 {
		t.Fatalf("line 7 series = %v, want exactly host=a", qSeries)
	}
	s0 := qSeries[0].(map[string]interface{})
	if s0["name"] != "cpu" || s0["labels"].(map[string]interface{})["host"] != "a" ||
		s0["count"].(float64) != 1 || s0["average"].(float64) != 2 {
		t.Fatalf("line 7 series[0] = %v, want cpu{host=a} count=1 average=2", s0)
	}

	// 行 8：合法批次正常新增。
	if m := decodeResultLine(t, lines[7]); m["status"] != "ok" ||
		m["added"].(float64) != 1 || m["duplicates"].(float64) != 0 {
		t.Fatalf("line 8 = %v, want added=1 duplicates=0", m)
	}

	// 行 9：两个点、均值 (2+4)/2 = 3。
	q = decodeResultLine(t, lines[8])
	if q["status"] != "ok" || q["op"] != "query" {
		t.Fatalf("line 9 = %v, want ok query", q)
	}
	qSeries = q["series"].([]interface{})
	if len(qSeries) != 1 {
		t.Fatalf("line 9 series = %v, want exactly host=a", qSeries)
	}
	s0 = qSeries[0].(map[string]interface{})
	if s0["name"] != "cpu" || s0["labels"].(map[string]interface{})["host"] != "a" ||
		s0["count"].(float64) != 2 || s0["average"].(float64) != 3 {
		t.Fatalf("line 9 series[0] = %v, want cpu{host=a} count=2 average=3", s0)
	}
}

package darksafe

import (
	"testing"
)

// 本文件回归保障写入批次在“不同采样点分别出现数值冲突与字段错误”时的错误选择，
// 以及同一采样点字段问题与数值冲突并存时的优先级。规则保持现状：
//
//   - 整行 JSON 合法时按数组先后报告第一个失败采样点（index 从 1 开始）：
//     先出现的数值冲突带完整 conflict 细节，后面采样点的类型错误不能替换它；
//     交换位置后则报告先出现的字段类型错误，不带 conflict，也不并列后面的冲突。
//   - 同一采样点只要带字段问题（如未知字段 bogus，即使 name/timestamp/value
//     都写在它前面），就报字段错误而不是数值冲突；删去未知字段后才是真正的冲突。
//   - 数组未闭合属于整行解析失败：即使前面的采样点已具备冲突条件，也只报
//     整行解析错误，不带 index 与 conflict。
//
// 每个失败批次都是原子的：批内排在前面的合法新增点不提交，已存原值不被覆盖；
// 随后合法批次仍可正常新增，查询统计随之更新。

// seedHostA 写入基线点：指标 cpu、标签 host=a、时间戳 1000、值 2。
func seedHostA(t *testing.T) *MetricStore {
	t.Helper()
	store := NewMetricStore()
	mustOK(t, store, `[{"name":"cpu","timestamp":1000,"value":2,"labels":{"host":"a"}}]`)
	return store
}

// assertConflictDetail 校验数值冲突结果的完整细节：index、错误文案、
// 指标名、完整标签集合、时间戳以及 existing/submitted 都必须精确对应被报告的点。
func assertConflictDetail(t *testing.T, lerr *LineError, wantIndex int, wantMsg string,
	wantName string, wantLabels map[string]string, wantTS int64, wantExisting, wantSubmitted float64) {
	t.Helper()
	if lerr == nil {
		t.Fatalf("expected conflict failure, got success")
	}
	if lerr.Index != wantIndex {
		t.Fatalf("index = %d, want %d (error: %s)", lerr.Index, wantIndex, lerr.Error)
	}
	if lerr.Error != wantMsg {
		t.Fatalf("error = %q, want %q", lerr.Error, wantMsg)
	}
	c := lerr.Conflict
	if c == nil {
		t.Fatalf("conflict failure must carry conflict detail, got %+v", lerr)
	}
	if c.Series.Name != wantName {
		t.Fatalf("conflict series name = %q, want %q", c.Series.Name, wantName)
	}
	if len(c.Series.Labels) != len(wantLabels) {
		t.Fatalf("conflict labels = %+v, want %+v", c.Series.Labels, wantLabels)
	}
	for k, v := range wantLabels {
		if got, ok := c.Series.Labels[k]; !ok || got != v {
			t.Fatalf("conflict labels = %+v, want %+v", c.Series.Labels, wantLabels)
		}
	}
	if c.Timestamp != wantTS || c.Existing != wantExisting || c.Submitted != wantSubmitted {
		t.Fatalf("conflict detail = ts %d existing %v submitted %v, want ts %d existing %v submitted %v",
			c.Timestamp, c.Existing, c.Submitted, wantTS, wantExisting, wantSubmitted)
	}
}

const conflictHostA1000Msg = `conflict: series cpu{host=a} at timestamp 1000 already has value 2, submitted 9`

// 整行合法、三个采样点：第一个是新时间戳上的合法新增，第二个与已存点冲突，
// 第三个 name 类型错误。必须只报告第二个点的数值冲突：index 为 2，
// conflict 中的指标名、完整标签、时间戳及 existing=2、submitted=9 全部对应它，
// 后面的类型错误不能替换该原因。
func TestConflictAtEarlierSampleBeatsLaterTypeError(t *testing.T) {
	store := seedHostA(t)

	lerr := mustFail(t, store, `[
		{"name":"cpu","timestamp":2000,"value":4,"labels":{"host":"a"}},
		{"name":"cpu","timestamp":1000,"value":9,"labels":{"host":"a"}},
		{"name":7,"timestamp":3000,"value":1,"labels":{"host":"a"}}
	]`)
	assertConflictDetail(t, lerr, 2, conflictHostA1000Msg,
		"cpu", map[string]string{"host": "a"}, 1000, 2, 9)

	// 整批原子回滚：第一个采样点（时间戳 2000 的新增）不得留下，
	// 时间戳 1000 上仍是原来的 2。
	assertStoreHasOnly(t, store, "cpu", 1000, 2)
}

// 交换冲突点与类型错误点的位置后：第二个采样点 name 为数字，必须报告该点的
// name 类型错误（index 仍为 2），不附带 conflict，也不同时列出后面第三个点
// 的数值冲突。
func TestFieldErrorAtEarlierSampleBeatsLaterConflict(t *testing.T) {
	store := seedHostA(t)

	lerr := mustFail(t, store, `[
		{"name":"cpu","timestamp":2000,"value":4,"labels":{"host":"a"}},
		{"name":7,"timestamp":3000,"value":1,"labels":{"host":"a"}},
		{"name":"cpu","timestamp":1000,"value":9,"labels":{"host":"a"}}
	]`)
	assertSampleError(t, lerr, 2, `field "name" must be a string`)

	// 失败批次前面的合法新增点同样不提交，基线数据保持原值。
	assertStoreHasOnly(t, store, "cpu", 1000, 2)
}

// 同一个采样点与已存点同序列、同时间戳且值不同，但还携带未知字段 bogus：
// 无论 bogus 写在所有已知字段之后，还是 name/timestamp/value 都写在 bogus
// 前面（labels 在其后），都只返回未知字段错误而不是数值冲突；删去 bogus、
// 其余内容不变后，才报告真正的数值冲突。
func TestUnknownFieldAtConflictingSampleMasksConflict(t *testing.T) {
	cases := []struct {
		name string
		line string
	}{
		// bogus 在 labels 之后：四个已知字段都先出现。
		{"bogus after all known fields",
			`[{"name":"cpu","timestamp":1000,"value":9,"labels":{"host":"a"},"bogus":1}]`},
		// name/timestamp/value 都写在 bogus 前面，labels 在 bogus 之后：结果相同。
		{"bogus between value and labels",
			`[{"name":"cpu","timestamp":1000,"value":9,"bogus":1,"labels":{"host":"a"}}]`},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			store := seedHostA(t)

			lerr := mustFail(t, store, tc.line)
			assertSampleError(t, lerr, 1, `unknown field "bogus"`)
			// 字段错误不允许伪装成冲突，原值 2 必须保留。
			assertStoreHasOnly(t, store, "cpu", 1000, 2)

			// 对照：删去未知字段、其余内容不变，同一时间戳才是真正的数值冲突。
			lerr = mustFail(t, store, `[{"name":"cpu","timestamp":1000,"value":9,"labels":{"host":"a"}}]`)
			assertConflictDetail(t, lerr, 1, conflictHostA1000Msg,
				"cpu", map[string]string{"host": "a"}, 1000, 2, 9)
			assertStoreHasOnly(t, store, "cpu", 1000, 2)
		})
	}
}

// 数组未闭合是整行解析失败：即使第一个采样点已具备与已存数据的冲突条件，
// 也只返回整行解析错误，不带 index 或 conflict；行内任何点都不提交。
func TestUnclosedArrayBeatsEarlierConflict(t *testing.T) {
	store := seedHostA(t)

	// 第一个点本身是新时间戳上的合法新增，第二个点（值 9）在同一序列的
	// 1000 上与已存值 2 冲突，但数组缺少闭合。
	_, lerr := store.IngestLine(`[
		{"name":"cpu","timestamp":2000,"value":4,"labels":{"host":"a"}},
		{"name":"cpu","timestamp":1000,"value":9,"labels":{"host":"a"}
	`)
	assertWholeLineTextError(t, lerr, "invalid JSON")

	// 整行失败：新增点未留下，原值未覆盖。
	assertStoreHasOnly(t, store, "cpu", 1000, 2)
}

// 连续多个失败批次之后，存储状态仍只有基线点；随后提交时间戳 2000、值 4 的
// 合法批次应正常新增，区间查询得到两个点、count=2、average=3。
func TestStoreStateAfterMixedFailuresThenRecovery(t *testing.T) {
	store := seedHostA(t)

	mustFail(t, store, `[
		{"name":"cpu","timestamp":2000,"value":4,"labels":{"host":"a"}},
		{"name":"cpu","timestamp":1000,"value":9,"labels":{"host":"a"}},
		{"name":7,"timestamp":3000,"value":1,"labels":{"host":"a"}}
	]`)
	mustFail(t, store, `[
		{"name":"cpu","timestamp":2000,"value":4,"labels":{"host":"a"}},
		{"name":7,"timestamp":3000,"value":1,"labels":{"host":"a"}},
		{"name":"cpu","timestamp":1000,"value":9,"labels":{"host":"a"}}
	]`)
	mustFail(t, store, `[{"name":"cpu","timestamp":1000,"value":9,"labels":{"host":"a"},"bogus":1}]`)

	// 恢复前：覆盖两个时间戳的区间只有一个点、均值 2。
	q := mustQuery(t, store, `{"op":"query","name":"cpu","start":0,"end":3000,"labels":{"host":"a"}}`)
	if len(q.Series) != 1 || q.Series[0].Count != 1 || q.Series[0].Average != 2 {
		t.Fatalf("query after failures = %+v, want one point average 2", q.Series)
	}

	// 合法批次正常新增。
	res := mustOK(t, store, `[{"name":"cpu","timestamp":2000,"value":4,"labels":{"host":"a"}}]`)
	if res.Added != 1 || res.Duplicates != 0 {
		t.Fatalf("recovery batch = %+v, want added=1 duplicates=0", res)
	}

	// 恢复后：两个点、均值 (2+4)/2 = 3。
	q = mustQuery(t, store, `{"op":"query","name":"cpu","start":0,"end":3000,"labels":{"host":"a"}}`)
	if len(q.Series) != 1 {
		t.Fatalf("query series = %+v, want exactly host=a", q.Series)
	}
	s0 := q.Series[0]
	if s0.Name != "cpu" || len(s0.Labels) != 1 || s0.Labels["host"] != "a" {
		t.Fatalf("query identity = %+v, want cpu{host=a}", s0)
	}
	if s0.Count != 2 || s0.Average != 3 {
		t.Fatalf("query after recovery = count %d average %v, want count 2 average 3",
			s0.Count, s0.Average)
	}
}

